(window.SLIDES = window.SLIDES || []).push(
  // ── Zinseszins ──
  { id: "fpr-001", cat: "finanzen", topic: "Zinseszins", type: "fact", emoji: "❄️", level: 1,
    title: "Zinseszins: Zinsen, die selbst Zinsen bringen",
    text: "Werden Erträge nicht entnommen, sondern wieder angelegt, wächst das Kapital exponentiell statt linear. Im Jahr 1 verzinst sich nur dein Einsatz, später auch alle bisherigen Zinsen.",
    more: "Darum ist **Zeit** der stärkste Hebel beim Vermögensaufbau – stärker als die Höhe der Rendite. Wichtig: Ausschüttungen nicht ausgeben, sondern reinvestieren (oder thesaurierende Fonds nutzen). Der Effekt wirkt übrigens genauso bei Schulden – gegen dich." },
  { id: "fpr-002", cat: "finanzen", topic: "Zinseszins", type: "number", emoji: "⏱️", level: 1,
    value: "72", label: "Regel 72: Jahre bis zur Verdopplung = 72 ÷ Zins",
    text: "Bei 6 % Rendite verdoppelt sich Geld in etwa 72 ÷ 6 = 12 Jahren, bei 3 % in rund 24 Jahren.",
    more: "Die Faustregel ist bei Zinsen zwischen 4 und 12 % sehr genau (exakt bei 6 %: 11,9 Jahre). Sie funktioniert auch rückwärts: Bei 3 % Inflation halbiert sich die Kaufkraft in rund 24 Jahren. Und bei 18 % Kreditkartenzins verdoppelt sich eine Schuld in nur 4 Jahren." },
  { id: "fpr-003", cat: "finanzen", topic: "Zinseszins", type: "quiz", emoji: "🧮", level: 1,
    q: "Nach der Regel 72: Wie lange dauert es ungefähr, bis sich Geld bei 8 % Rendite pro Jahr verdoppelt?",
    options: ["6 Jahre", "9 Jahre", "12 Jahre", "16 Jahre"], answer: 1,
    explain: "72 ÷ 8 = 9 Jahre. Exakt sind es 9,0 Jahre – die Regel ist im Bereich um 8 % fast perfekt." },
  { id: "fpr-004", cat: "finanzen", topic: "Zinseszins", type: "quiz", emoji: "📈", level: 2,
    q: "Du legst einmalig 10.000 € zu 7 % pro Jahr an und lässt alles 30 Jahre liegen. Wie viel hast du ungefähr?",
    options: ["31.000 €", "52.000 €", "61.000 €", "76.000 €"], answer: 3,
    explain: "10.000 × 1,07³⁰ ≈ 76.100 €. Linear (ohne Zinseszins) wären es nur 10.000 + 30 × 700 = 31.000 €. Der Unterschied von 45.000 € ist reiner Zinseszins." },
  { id: "fpr-005", cat: "finanzen", topic: "Zinseszins", type: "whatif", emoji: "🚀", level: 2,
    q: "Was passiert, wenn du 10 Jahre früher mit dem Sparen anfängst?",
    steps: ["200 €/Monat ab 25 statt ab 35", "Nur 24.000 € mehr eingezahlt", "10 Jahre mehr Zinseszins-Zeit", "Bei 7 %: ca. 574.000 € statt 274.000 € mit 67"],
    text: "Die zusätzlichen 10 Jahre stehen am Anfang, wirken aber am Ende: Das früh investierte Geld hat am längsten Zeit zu wachsen. Ein Start mit kleinen Beträgen schlägt einen späten Start mit großen fast immer." },
  { id: "fpr-006", cat: "finanzen", topic: "Zinseszins", type: "truefalse", emoji: "🐢", level: 1,
    q: "Mit 50 € im Monat lohnt sich Sparen nicht – da kommt nichts Nennenswertes zusammen.",
    answer: false,
    explain: "50 € monatlich über 40 Jahre bei 6 % ergeben rund 96.000 € – bei nur 24.000 € Einzahlung. Kleine Beträge plus viel Zeit sind mächtig. Und: Die Gewohnheit zählt, die Rate kann später steigen." },
  { id: "fpr-007", cat: "finanzen", topic: "Zinseszins", type: "flashcard", emoji: "📐", level: 2,
    term: "Exponentielles vs. lineares Wachstum",
    def: "Linear: jedes Jahr derselbe Zuwachs (z. B. +700 €). Exponentiell: jedes Jahr derselbe Prozentsatz auf einen wachsenden Betrag – die Kurve wird immer steiler.",
    example: "Bei 7 % verdoppelt sich Geld ca. alle 10 Jahre: 10.000 → 20.000 → 40.000 → 80.000 € (nach 30 Jahren)." },
  { id: "fpr-008", cat: "finanzen", topic: "Zinseszins", type: "quiz", emoji: "💡", level: 2,
    q: "Was beeinflusst das Endvermögen bei langfristigem Sparen typischerweise am stärksten?",
    options: ["Die Anlagedauer", "Der Einstiegszeitpunkt im Jahr", "Die Wahl des Wochentags für den Sparplan", "Ob die Bank eine Filiale hat"], answer: 0,
    explain: "Die Dauer geht im Exponenten der Zinseszinsformel ein (Kapital × (1 + r)ⁿ). Zeitpunkt im Jahr oder Ausführungstag spielen langfristig praktisch keine Rolle." },

  // ── Inflation ──
  { id: "fpr-009", cat: "finanzen", topic: "Inflation", type: "fact", emoji: "🎈", level: 1,
    title: "Inflation frisst dein Geld leise auf",
    text: "Inflation bedeutet steigende Preise – für denselben Euro bekommst du jedes Jahr weniger. Geld auf dem Girokonto ohne Zinsen verliert damit Jahr für Jahr real an Wert.",
    more: "Die EZB strebt mittelfristig 2 % Inflation an. Klingt wenig, ist aber über Jahrzehnte enorm: Nach 30 Jahren mit 2 % ist ein Euro nur noch rund 55 Cent wert. Wer langfristig spart, muss daher mindestens die Inflation erwirtschaften, um nicht ärmer zu werden." },
  { id: "fpr-010", cat: "finanzen", topic: "Inflation", type: "number", emoji: "📉", level: 1,
    value: "55 Cent", label: "Kaufkraft von 1 € nach 30 Jahren bei 2 % Inflation",
    text: "1 ÷ 1,02³⁰ ≈ 0,55. Selbst die „normale“ Zielinflation der EZB halbiert die Kaufkraft fast innerhalb eines Berufslebens.",
    more: "Praxis: Wenn du für die Rente planst, rechne in heutiger Kaufkraft. 2.000 € Rentenbedarf heute entsprechen bei 2 % Inflation in 30 Jahren rund 3.600 € nominal. Rentenrechner, die das ignorieren, zeichnen ein zu rosiges Bild." },
  { id: "fpr-011", cat: "finanzen", topic: "Inflation", type: "number", emoji: "🔥", level: 2,
    value: "6,9 %", label: "Inflationsrate in Deutschland 2022 (Jahresdurchschnitt)",
    text: "Der höchste Wert seit Jahrzehnten – getrieben vor allem durch Energie- und Lebensmittelpreise nach dem russischen Angriff auf die Ukraine. 2023 lag die Rate bei 5,9 %.",
    more: "Für Sparer war das bitter: Tagesgeld brachte 2022 oft noch fast 0 %. Real verlor man also fast 7 % Kaufkraft in einem Jahr. Lehre: Hohe Inflation trifft Geldvermögen und Menschen mit festem Einkommen am härtesten – Sachwerte und Schuldner eher weniger." },
  { id: "fpr-012", cat: "finanzen", topic: "Inflation", type: "quiz", emoji: "🛒", level: 2,
    q: "Bei 3 % Inflation pro Jahr: Nach etwa wie vielen Jahren hat sich die Kaufkraft deines Geldes halbiert?",
    options: ["Ca. 12 Jahre", "Ca. 18 Jahre", "Ca. 33 Jahre", "Ca. 24 Jahre"], answer: 3,
    explain: "Regel 72: 72 ÷ 3 = 24 Jahre. Rechnerisch: 1 ÷ 1,03²⁴ ≈ 0,49 – also tatsächlich knapp die Hälfte." },
  { id: "fpr-013", cat: "finanzen", topic: "Inflation", type: "whatif", emoji: "🌡️", level: 2,
    q: "Was passiert, wenn die Inflation 5 % beträgt und dein Tagesgeld 2 % bringt?",
    steps: ["Konto wächst nominal um 2 %", "Preise steigen um 5 %", "Realzins: ca. −2,9 % pro Jahr", "10.000 € haben nach 10 Jahren Kaufkraft von ~7.500 €"],
    text: "Der Kontostand steigt, trotzdem wirst du ärmer – das ist **Geldillusion**. Rechnung: 1,02 ÷ 1,05 − 1 ≈ −2,9 %. Nach Steuern auf die Zinsen sieht es noch schlechter aus. Tagesgeld ist für den Notgroschen gut, nicht für langfristigen Vermögensaufbau." },
  { id: "fpr-014", cat: "finanzen", topic: "Inflation", type: "truefalse", emoji: "🛏️", level: 1,
    q: "Bargeld unter der Matratze ist die sicherste Form, Vermögen langfristig zu erhalten.",
    answer: false,
    explain: "Nominal bleibt es gleich, real verliert es jedes Jahr um die Inflationsrate an Wert – bei 2 % nach 35 Jahren etwa die Hälfte. Dazu kommen Diebstahl- und Brandrisiko. „Sicher“ ist nur der Nennwert, nicht die Kaufkraft." },
  { id: "fpr-015", cat: "finanzen", topic: "Inflation", type: "flashcard", emoji: "🧺", level: 2,
    term: "Verbraucherpreisindex (VPI)",
    def: "Misst die Preisentwicklung eines repräsentativen Warenkorbs, den private Haushalte kaufen. Seine Veränderung zum Vorjahr ist die offizielle Inflationsrate in Deutschland (Statistisches Bundesamt).",
    example: "Deine persönliche Inflation kann abweichen: Wer viel Energie verbraucht oder in der Stadt neu mietet, spürt oft mehr als den Durchschnitt." },

  // ── Realzins ──
  { id: "fpr-016", cat: "finanzen", topic: "Realzins", type: "flashcard", emoji: "⚖️", level: 1,
    term: "Realzins vs. Nominalzins",
    def: "Nominalzins: der Zins, den die Bank nennt. Realzins: Nominalzins minus Inflation (näherungsweise). Nur der Realzins zeigt, ob deine Kaufkraft wächst.",
    example: "3 % Festgeld bei 2 % Inflation → ca. +1 % real. 3 % Festgeld bei 4 % Inflation → ca. −1 % real." },
  { id: "fpr-017", cat: "finanzen", topic: "Realzins", type: "quiz", emoji: "🧾", level: 3,
    q: "Tagesgeld bringt 2,5 %, die Zinsen werden voll mit 26,375 % besteuert (Freibetrag ausgeschöpft), Inflation 2 %. Wie hoch ist der reale Nachsteuer-Zins ungefähr?",
    options: ["+0,5 %", "−0,2 %", "+1,8 %", "0,0 %"], answer: 1,
    explain: "Nach Steuern bleiben 2,5 % × (1 − 0,26375) ≈ 1,84 %. Minus 2 % Inflation ≈ −0,2 % real. Steuern werden auf den Nominalzins erhoben – auch auf den Teil, der nur die Inflation ausgleicht." },
  { id: "fpr-018", cat: "finanzen", topic: "Realzins", type: "truefalse", emoji: "🪙", level: 2,
    q: "Auch mit 4 % Zinsen auf dem Konto kann dein Vermögen real an Wert verlieren.",
    answer: true,
    explain: "Real wächst es nur, wenn die Inflation (und die Steuer auf die Zinsen) darunter liegt. Beispiel 2023: Festgeld brachte teils 3–4 %, die Inflation lag aber bei 5,9 %. Entscheidend ist immer der Realzins nach Steuern." },
  { id: "fpr-019", cat: "finanzen", topic: "Realzins", type: "fact", emoji: "🔍", level: 3,
    title: "Fisher-Gleichung: die exakte Formel",
    text: "Exakt gilt: (1 + Nominalzins) = (1 + Realzins) × (1 + Inflation). Die Faustformel „Nominal minus Inflation“ ist nur bei kleinen Werten genau.",
    more: "Beispiel: 10 % Zins bei 8 % Inflation → Faustformel 2 %, exakt 1,10 ÷ 1,08 − 1 = 1,85 %. Bei niedrigen Raten ist der Unterschied vernachlässigbar, bei hoher Inflation (z. B. in Schwellenländern) aber deutlich." },

  // ── Notgroschen ──
  { id: "fpr-020", cat: "finanzen", topic: "Notgroschen", type: "number", emoji: "🛟", level: 1,
    value: "3–6", label: "Monatsausgaben als Notgroschen (Faustregel)",
    text: "Ein Puffer auf dem Tagesgeldkonto für kaputte Waschmaschine, Autoreparatur oder Jobverlust – jederzeit verfügbar, nicht investiert.",
    more: "Berechne ihn nach **Ausgaben**, nicht nach Einkommen. Selbstständige, Alleinverdiener oder Immobilienbesitzer eher Richtung 6 Monate und mehr. Ohne Notgroschen musst du im Ernstfall Aktien im Crash verkaufen oder teuren Dispo nutzen – genau das soll er verhindern." },
  { id: "fpr-021", cat: "finanzen", topic: "Notgroschen", type: "quiz", emoji: "🏦", level: 1,
    q: "Wo gehört der Notgroschen am ehesten hin?",
    options: ["Aufs Tagesgeldkonto", "In einen Aktien-ETF", "In eine 5-jährige Festgeldanlage", "In Gold"], answer: 0,
    explain: "Der Notgroschen muss sofort und ohne Kursrisiko verfügbar sein. Tagesgeld ist täglich verfügbar und bis 100.000 € pro Bank durch die gesetzliche Einlagensicherung geschützt." },
  { id: "fpr-022", cat: "finanzen", topic: "Notgroschen", type: "whatif", emoji: "🧯", level: 2,
    q: "Was passiert, wenn du keinen Notgroschen hast und das Auto plötzlich 2.500 € kostet?",
    steps: ["Konto rutscht in den Dispo", "Dispozins oft über 10 % p. a.", "Oder: ETF-Verkauf, evtl. im Minus", "Sparplan wird pausiert, Plan gerät ins Wanken"],
    text: "Ein Notgroschen ist keine „tote“ Rendite, sondern eine Versicherung: Er schützt dein Investment davor, im falschen Moment verkauft zu werden, und dich vor teuren Krediten." },
  { id: "fpr-023", cat: "finanzen", topic: "Notgroschen", type: "order", emoji: "🪜", level: 2,
    q: "Bringe die klassische Reihenfolge beim Geldordnen in eine sinnvolle Abfolge:",
    items: ["Teure Schulden (Dispo, Kreditkarte) tilgen", "Notgroschen aufbauen", "Existenzielle Risiken versichern (Haftpflicht, BU)", "Langfristig investieren (z. B. ETF-Sparplan)"],
    explain: "Kein Investment schlägt verlässlich 10–18 % Kreditzins, also zuerst teure Schulden weg. Der Notgroschen verhindert neue Schulden. Versicherungen schützen vor dem Totalschaden – danach baut man Vermögen auf." },

  // ── Budget ──
  { id: "fpr-024", cat: "finanzen", topic: "Budget", type: "flashcard", emoji: "🍰", level: 1,
    term: "50/30/20-Regel",
    def: "Faustregel fürs Nettoeinkommen: 50 % für Bedürfnisse (Miete, Essen, Versicherungen), 30 % für Wünsche (Freizeit, Reisen), 20 % zum Sparen und Schuldenabbau.",
    example: "2.800 € netto → 1.400 € Fixkosten, 840 € Lifestyle, 560 € Sparen. Popularisiert von Elizabeth Warren im Buch „All Your Worth“ (2005)." },
  { id: "fpr-025", cat: "finanzen", topic: "Budget", type: "quiz", emoji: "🧮", level: 1,
    q: "Du verdienst 3.200 € netto. Wie viel solltest du nach der 50/30/20-Regel monatlich sparen?",
    options: ["640 €", "480 €", "320 €", "960 €"], answer: 0,
    explain: "20 % von 3.200 € = 640 €. 1.600 € gehen in Bedürfnisse, 960 € in Wünsche. In teuren Städten sind 50 % Fixkosten oft schwer – dann eher bei Wünschen kürzen als beim Sparen." },
  { id: "fpr-026", cat: "finanzen", topic: "Budget", type: "fact", emoji: "💸", level: 1,
    title: "Pay yourself first: Erst sparen, dann ausgeben",
    text: "Lass am Monatsanfang per Dauerauftrag oder Sparplan automatisch einen festen Betrag abgehen – direkt nach Gehaltseingang. Ausgegeben wird nur, was übrig bleibt.",
    more: "Wer am Monatsende spart, was übrig ist, spart meist nichts: Ausgaben dehnen sich auf das verfügbare Geld aus. Automatisierung nimmt die Willenskraft aus der Gleichung. Verhaltensökonomisch nutzt man so den Status-quo-Bias zu seinen Gunsten." },
  { id: "fpr-027", cat: "finanzen", topic: "Budget", type: "number", emoji: "🐷", level: 2,
    value: "≈ 11 %", label: "Sparquote der privaten Haushalte in Deutschland",
    text: "Von 100 € verfügbarem Einkommen werden im Schnitt rund 11 € gespart (Größenordnung der Jahre 2023/2024, Statistisches Bundesamt).",
    more: "Die Sparquote ist der wichtigste Hebel, den du selbst kontrollierst – die Rendite nicht. Faustregel: Wer 10 % spart, braucht sehr lange bis zur finanziellen Unabhängigkeit; wer 50 % spart, kann es in rund 17 Jahren schaffen. Achtung: Deutsche sparen viel, legen aber oft renditeschwach an." },
  { id: "fpr-028", cat: "finanzen", topic: "Budget", type: "flashcard", emoji: "🎈", level: 1,
    term: "Lifestyle-Inflation",
    def: "Mit jeder Gehaltserhöhung steigen auch die Ausgaben – größere Wohnung, neueres Auto, teurere Urlaube. Das Vermögen wächst trotz höherem Einkommen kaum.",
    example: "Gegenmittel: Bei jeder Gehaltserhöhung mindestens die Hälfte des Netto-Plus sofort in den Sparplan leiten." },
  { id: "fpr-029", cat: "finanzen", topic: "Budget", type: "whatif", emoji: "📊", level: 2,
    q: "Was passiert, wenn du nach jeder Gehaltserhöhung 50 % des Plus sparst?",
    steps: ["Netto steigt um 200 €", "100 € gehen direkt in den Sparplan", "Lebensstandard steigt trotzdem spürbar", "Sparquote wächst Jahr für Jahr automatisch"],
    text: "Du verzichtest auf nichts, was du schon hattest – Verlustaversion schlägt nicht zu. Gleichzeitig erhöht sich die Sparquote über die Jahre deutlich, ohne dass es sich wie Verzicht anfühlt." },
  { id: "fpr-030", cat: "finanzen", topic: "Budget", type: "truefalse", emoji: "📒", level: 1,
    q: "Ein Haushaltsbuch lohnt sich nur für Menschen mit Geldproblemen.",
    answer: false,
    explain: "Die meisten unterschätzen ihre Ausgaben – besonders Abos, Lieferdienste und Kleinbeträge. Schon 2–3 Monate Tracking zeigen, wo das Geld wirklich hingeht. Das ist die Basis für jede bewusste Sparentscheidung." },

  // ── Opportunitätskosten ──
  { id: "fpr-031", cat: "finanzen", topic: "Opportunitätskosten", type: "flashcard", emoji: "🔀", level: 1,
    term: "Opportunitätskosten",
    def: "Der entgangene Nutzen der besten Alternative, auf die man verzichtet. Jeder Euro, den du ausgibst, kann nicht mehr investiert werden und wachsen.",
    example: "Ein 30.000-€-Neuwagen statt eines 15.000-€-Gebrauchten: Die 15.000 € Differenz wären bei 7 % in 20 Jahren rund 58.000 €." },
  { id: "fpr-032", cat: "finanzen", topic: "Opportunitätskosten", type: "quiz", emoji: "☕", level: 2,
    q: "3 € täglich für Coffee-to-go sind rund 90 € im Monat. Was ergäben 90 €/Monat, 30 Jahre lang zu 7 % angelegt, ungefähr?",
    options: ["Ca. 32.000 €", "Ca. 55.000 €", "Ca. 106.000 €", "Ca. 250.000 €"], answer: 2,
    explain: "Rund 106.000 € – bei nur 32.400 € Einzahlungen. Das heißt nicht „kein Kaffee“, sondern: Kleine Dauer-Ausgaben bewusst wählen. Viel mehr bringen allerdings die großen Posten: Miete, Auto, Versicherungen." },
  { id: "fpr-033", cat: "finanzen", topic: "Opportunitätskosten", type: "truefalse", emoji: "🚗", level: 2,
    q: "Beim Sparen bringen die großen Fixkosten (Wohnen, Auto) meist mehr als das Streichen kleiner Alltagsausgaben.",
    answer: true,
    explain: "Wohnen und Mobilität sind für die meisten Haushalte die größten Ausgabenblöcke. 100 € weniger Miete oder Autokosten wirken jeden Monat automatisch – ohne tägliche Willenskraft. Kleinvieh macht auch Mist, aber erst die großen Brocken prüfen." },

  // ── ETF-Sparplan ──
  { id: "fpr-034", cat: "finanzen", topic: "ETF-Sparplan", type: "flashcard", emoji: "🧺", level: 1,
    term: "ETF (Exchange Traded Fund)",
    def: "Börsengehandelter Indexfonds, der einen Index wie den MSCI World passiv nachbildet. Mit einem Kauf besitzt man Anteile an Hunderten oder Tausenden Unternehmen – meist zu sehr niedrigen Kosten.",
    example: "Ein ETF auf den MSCI World enthält rund 1.300–1.400 Unternehmen aus 23 Industrieländern." },
  { id: "fpr-035", cat: "finanzen", topic: "ETF-Sparplan", type: "fact", emoji: "🔁", level: 1,
    title: "Der ETF-Sparplan: Vermögensaufbau auf Autopilot",
    text: "Monatlich wird automatisch ein fester Betrag (oft schon ab 1–25 €) in einen ETF investiert. Kein Timing, keine Einzelaktienauswahl, wenig Aufwand.",
    more: "Die Stärke liegt im Verhalten: Man investiert regelmäßig, auch in Krisen, und verbindet „Pay yourself first“ mit breiter Streuung. Wichtig ist, ihn in Crashs **nicht** zu stoppen – gerade dann kauft man günstig. Die Rendite ist nicht garantiert; Aktien schwanken stark." },
  { id: "fpr-036", cat: "finanzen", topic: "ETF-Sparplan", type: "flashcard", emoji: "⚖️", level: 2,
    term: "Cost-Average-Effekt",
    def: "Bei festen Sparraten kauft man bei niedrigen Kursen automatisch mehr Anteile, bei hohen weniger. Der durchschnittliche Kaufpreis liegt dadurch unter dem Durchschnitt der Kurse.",
    example: "100 € zu Kursen von 10 €, 5 €, 10 € → 10 + 20 + 10 = 40 Anteile für 300 € = 7,50 € je Anteil. Durchschnittskurs: 8,33 €." },
  { id: "fpr-037", cat: "finanzen", topic: "ETF-Sparplan", type: "truefalse", emoji: "🎯", level: 3,
    q: "Wer einen größeren Betrag hat, fährt mit einem Sparplan (Cost-Average) statistisch besser als mit einer Einmalanlage.",
    answer: false,
    explain: "Da Aktienmärkte langfristig meist steigen, schlägt die sofortige Einmalanlage das Aufteilen in historischen Studien in rund zwei Dritteln der Fälle. Der Sparplan reduziert vor allem das Bedauerns-Risiko – psychologisch wertvoll, aber keine Renditegarantie." },
  { id: "fpr-038", cat: "finanzen", topic: "ETF-Sparplan", type: "quiz", emoji: "🧮", level: 2,
    q: "Du sparst 300 €/Monat 30 Jahre lang. Wie viel hast du selbst eingezahlt?",
    options: ["36.000 €", "90.000 €", "108.000 €", "180.000 €"], answer: 2,
    explain: "300 € × 12 × 30 = 108.000 €. Bei angenommenen 7 % pro Jahr könnten daraus rund 350.000 € werden – mehr als zwei Drittel wären dann Erträge. Historische Renditen sind aber keine Garantie." },
  { id: "fpr-039", cat: "finanzen", topic: "ETF-Sparplan", type: "quiz", emoji: "🧩", level: 1,
    q: "Was ist der Hauptunterschied zwischen einem ETF und einem klassischen aktiv gemanagten Fonds?",
    options: ["ETFs bilden passiv einen Index ab und sind meist deutlich günstiger", "ETFs sind gesetzlich garantiert", "ETFs dürfen nur Anleihen enthalten", "ETFs schütten nie aus"], answer: 0,
    explain: "Ein ETF kopiert einen Index statt Aktien auszuwählen. Das spart Fondsmanager-Kosten: oft 0,1–0,3 % pro Jahr statt 1,5–2 %. Einen Kapitalschutz gibt es nicht – aber Fonds sind **Sondervermögen** und bei einer Pleite der Fondsgesellschaft geschützt." },
  { id: "fpr-040", cat: "finanzen", topic: "ETF-Sparplan", type: "flashcard", emoji: "🔄", level: 2,
    term: "Thesaurierend vs. ausschüttend",
    def: "Thesaurierende ETFs legen Dividenden automatisch wieder an, ausschüttende zahlen sie aufs Konto aus. Langfristig ähnlich – entscheidend ist, ausgeschüttetes Geld wieder zu investieren.",
    example: "Thesaurierer nutzen den Zinseszins ohne eigenes Zutun; Ausschütter passen zu jemandem, der regelmäßige Erträge entnehmen will." },
  { id: "fpr-041", cat: "finanzen", topic: "ETF-Sparplan", type: "whatif", emoji: "🌧️", level: 2,
    q: "Was passiert, wenn du deinen Sparplan im Crash aus Angst stoppst?",
    steps: ["Kurse fallen z. B. um 30 %", "Du kaufst nichts mehr zu Tiefpreisen", "Erholung beginnt oft unerwartet schnell", "Du verpasst die günstigsten Käufe"],
    text: "Der Cost-Average-Effekt lebt gerade von Krisen. Wer dann aussteigt, kauft nur in teuren Phasen. Viele der besten Börsentage liegen direkt neben den schlechtesten – Timing gelingt fast niemandem verlässlich." },

  // ── Kosten ──
  { id: "fpr-042", cat: "finanzen", topic: "Kosten", type: "flashcard", emoji: "🏷️", level: 1,
    term: "TER (Total Expense Ratio)",
    def: "Gesamtkostenquote eines Fonds pro Jahr in Prozent des Fondsvermögens. Wird automatisch aus dem Fonds entnommen – du siehst sie nie als Rechnung, nur in der geringeren Rendite.",
    example: "Breite Welt-ETFs: ca. 0,1–0,3 %. Aktive Aktienfonds: oft 1,5–2 %. Transaktionskosten im Fonds sind in der TER nicht enthalten." },
  { id: "fpr-043", cat: "finanzen", topic: "Kosten", type: "number", emoji: "💶", level: 3,
    value: "≈ 70.000 €", label: "Kostenunterschied: Sparplan mit 0,2 % vs. 1,5 % TER",
    text: "300 €/Monat über 30 Jahre bei 7 % Bruttorendite: ca. 340.000 € (0,2 % TER) vs. ca. 268.000 € (1,5 % TER). Der Unterschied: rund 70.000 €.",
    more: "Kosten wirken wie negativer Zinseszins: Sie werden jedes Jahr auf das wachsende Vermögen fällig. Rund ein Fünftel des Endvermögens geht hier verloren – nur durch 1,3 Prozentpunkte. Merksatz: Rendite ist unsicher, Kosten sind sicher." },
  { id: "fpr-044", cat: "finanzen", topic: "Kosten", type: "quiz", emoji: "🎟️", level: 2,
    q: "Ein Fonds hat 5 % Ausgabeaufschlag. Du zahlst 1.000 € ein. Wie viel wird tatsächlich angelegt?",
    options: ["1.000 €", "Ca. 952 €", "950 €", "Ca. 900 €"], answer: 1,
    explain: "Der Aufschlag wird auf den Anteilspreis berechnet: 1.000 ÷ 1,05 ≈ 952 €. Rund 48 € sind sofort weg – der Fonds muss erst einmal fast 5 % Rendite erwirtschaften, nur um bei null zu sein." },
  { id: "fpr-045", cat: "finanzen", topic: "Kosten", type: "truefalse", emoji: "💎", level: 2,
    q: "Teurere Fonds bringen im Schnitt mehr Rendite – Qualität hat eben ihren Preis.",
    answer: false,
    explain: "Studien wie die SPIVA-Berichte von S&P zeigen: Über 15 Jahre schlagen nur ein kleiner Teil (oft unter 10–15 %) der aktiven Aktienfonds ihren Vergleichsindex. Die höheren Kosten sind einer der Hauptgründe." },

  // ── Diversifikation ──
  { id: "fpr-046", cat: "finanzen", topic: "Diversifikation", type: "fact", emoji: "🥚", level: 1,
    title: "Nicht alle Eier in einen Korb",
    text: "Diversifikation heißt: Geld auf viele Unternehmen, Branchen und Länder streuen. Fällt eine Firma aus, ist es ein kleiner Kratzer statt eines Totalverlusts.",
    more: "Streuung senkt das **unsystematische** Risiko (Einzelfirmen-Pleite) fast kostenlos. Das **systematische** Marktrisiko (z. B. weltweiter Crash) bleibt – dafür gibt es langfristig die Risikoprämie. Ein Welt-ETF diversifiziert breiter als jedes selbst gebaute Depot aus 10 Aktien." },
  { id: "fpr-047", cat: "finanzen", topic: "Diversifikation", type: "truefalse", emoji: "🏢", level: 2,
    q: "Aktien des eigenen Arbeitgebers sind ein gutes Kerninvestment, weil man die Firma ja kennt.",
    answer: false,
    explain: "Gerät die Firma in die Krise, verlierst du womöglich Job **und** Ersparnisse gleichzeitig – ein Klumpenrisiko. Mahnendes Beispiel: Enron (2001), wo viele Mitarbeiter ihre Altersvorsorge in Firmenaktien hielten." },
  { id: "fpr-048", cat: "finanzen", topic: "Diversifikation", type: "quiz", emoji: "🌍", level: 2,
    q: "Welches Depot ist am breitesten diversifiziert?",
    options: ["5 deutsche DAX-Aktien", "Ein Branchen-ETF auf Technologie", "Eine Aktie eines großen Weltkonzerns", "Ein ETF auf einen globalen Aktienindex mit tausenden Firmen"], answer: 3,
    explain: "Ein globaler Index streut über Länder, Branchen und tausende Unternehmen. Branchen- oder Länder-ETFs sind zwar Fonds, aber konzentriert. Beachte: Auch Welt-Indizes haben derzeit einen hohen USA- und Tech-Anteil." },
  { id: "fpr-049", cat: "finanzen", topic: "Diversifikation", type: "flashcard", emoji: "🏠", level: 3,
    term: "Home Bias",
    def: "Die Neigung, überproportional in Aktien des eigenen Landes zu investieren. Deutschland macht nur rund 2 % der weltweiten Börsenwerte aus – ein reines DAX-Depot ist also stark konzentriert.",
    example: "Wer in Deutschland lebt, arbeitet und eine Immobilie besitzt, ist ohnehin schon stark vom deutschen Wirtschaftsraum abhängig." },

  // ── Risiko & Horizont ──
  { id: "fpr-050", cat: "finanzen", topic: "Risiko & Horizont", type: "fact", emoji: "🎢", level: 1,
    title: "Anlagehorizont bestimmt das Risiko, das du tragen kannst",
    text: "Geld, das du in 1–3 Jahren brauchst, gehört nicht in Aktien. Bei 15+ Jahren können Aktien ihre Schwankungen meist ausgleichen – historisch gab es in breiten Weltindizes nach so langen Zeiträumen selten Verluste.",
    more: "Faustregel: Je kürzer der Horizont, desto sicherer die Anlage. Ein Crash von −50 % braucht +100 %, um wieder auszugleichen – das kann Jahre dauern. Teile dein Geld nach Zweck auf: Notgroschen, mittelfristige Ziele (Auto, Eigenkapital), Altersvorsorge." },
  { id: "fpr-051", cat: "finanzen", topic: "Risiko & Horizont", type: "quiz", emoji: "📉", level: 2,
    q: "Dein Depot fällt um 50 %. Wie viel Prozent Plus brauchst du, um wieder auf den Ausgangswert zu kommen?",
    options: ["50 %", "75 %", "100 %", "150 %"], answer: 2,
    explain: "Aus 10.000 € werden 5.000 €. Um wieder 10.000 € zu erreichen, braucht es +5.000 € auf 5.000 € – also +100 %. Verluste wiegen mathematisch schwerer als Gewinne gleicher Prozenthöhe." },
  { id: "fpr-052", cat: "finanzen", topic: "Risiko & Horizont", type: "flashcard", emoji: "🧭", level: 2,
    term: "Risikotragfähigkeit vs. Risikobereitschaft",
    def: "Tragfähigkeit: Wie viel Verlust kannst du finanziell verkraften (Einkommen, Horizont, Notgroschen)? Bereitschaft: Wie viel hältst du emotional aus, ohne panisch zu verkaufen?",
    example: "Ein 25-Jähriger kann 100 % Aktien tragen – wer aber bei −30 % nachts nicht schläft und verkauft, sollte eine sichere Beimischung wählen." },
  { id: "fpr-053", cat: "finanzen", topic: "Risiko & Horizont", type: "flashcard", emoji: "🎛️", level: 3,
    term: "Risikoarmer Anteil (Asset Allocation)",
    def: "Aufteilung des Vermögens in einen risikoreichen (Aktien) und einen risikoarmen Teil (Tagesgeld, Festgeld, kurzlaufende Staatsanleihen guter Bonität). Über das Verhältnis steuerst du das Gesamtrisiko.",
    example: "70/30: 70 % Welt-ETF, 30 % Tagesgeld. Fallen Aktien um 40 %, verliert das Gesamtdepot rund 28 %." },
  { id: "fpr-054", cat: "finanzen", topic: "Risiko & Horizont", type: "whatif", emoji: "🎲", level: 3,
    q: "Was passiert, wenn ein Crash ausgerechnet zu Beginn deiner Entnahmephase kommt?",
    steps: ["Depot 500.000 €, Entnahme 30.000 €/Jahr", "Jahr 1–2: −25 % und −15 %", "Entnahmen verkaufen Anteile zu Tiefstkursen", "Danach 7 %/Jahr: Depot im Jahr 16 leer"],
    text: "Das ist das **Sequence-of-returns-Risiko**: Kommt derselbe Crash erst nach 18 guten Jahren, bleiben nach 20 Jahren noch über 330.000 €. Gleiche Durchschnittsrendite, völlig anderes Ergebnis – weil Entnahmen Verluste festschreiben." },
  { id: "fpr-055", cat: "finanzen", topic: "Risiko & Horizont", type: "truefalse", emoji: "🔮", level: 2,
    q: "Profis können Börsencrashs zuverlässig vorhersagen – man muss nur den richtigen Experten folgen.",
    answer: false,
    explain: "Market-Timing gelingt auch Profis nicht verlässlich. Man müsste zweimal richtig liegen: beim Aus- und beim Wiedereinstieg. Wer die zehn besten Börsentage eines Jahrzehnts verpasst, verliert einen großen Teil der Rendite." },

  // ── Entnahme ──
  { id: "fpr-056", cat: "finanzen", topic: "Entnahme", type: "number", emoji: "🧓", level: 2,
    value: "4 %", label: "„Sichere“ Entnahmerate laut Trinity-Studie",
    text: "Wer im ersten Jahr 4 % seines Depots entnimmt und den Betrag danach jährlich um die Inflation erhöht, wäre in US-Daten über 30 Jahre fast immer ausgekommen.",
    more: "Basis: William Bengen (1994) und die Trinity-Studie (1998) mit US-Aktien und -Anleihen. Bei 1 Mio. € wären das 40.000 € im ersten Jahr. Umgekehrt: Jahresausgaben × 25 = benötigtes Vermögen. Es ist eine Faustregel, kein Naturgesetz." },
  { id: "fpr-057", cat: "finanzen", topic: "Entnahme", type: "quiz", emoji: "🧮", level: 2,
    q: "Du willst nach der 4-%-Regel jährlich 30.000 € entnehmen. Wie groß muss dein Depot ungefähr sein?",
    options: ["300.000 €", "750.000 €", "120.000 €", "1,2 Mio. €"], answer: 1,
    explain: "30.000 € ÷ 0,04 = 30.000 × 25 = 750.000 €. Daraus stammt die FIRE-Faustregel „25-mal die Jahresausgaben“." },
  { id: "fpr-058", cat: "finanzen", topic: "Entnahme", type: "fact", emoji: "⚠️", level: 3,
    title: "Kritik an der 4-%-Regel",
    text: "Sie basiert auf US-Daten (einem historisch außergewöhnlich erfolgreichen Markt), einem 30-Jahre-Horizont und ignoriert Steuern und Fondskosten. Für Frührentner mit 40–50 Jahren Entnahme ist sie zu optimistisch.",
    more: "Viele Planer rechnen für lange Zeiträume eher mit 3–3,5 %. Flexible Strategien helfen: in schlechten Börsenjahren weniger entnehmen, einen Cash-Puffer für 1–2 Jahre halten. So begegnet man auch dem Sequence-of-returns-Risiko." },
  { id: "fpr-059", cat: "finanzen", topic: "Entnahme", type: "flashcard", emoji: "🏝️", level: 1,
    term: "FIRE",
    def: "„Financial Independence, Retire Early“: Bewegung, die durch hohe Sparquoten (oft 40–70 %) früh finanzielle Unabhängigkeit anstrebt – also so viel Vermögen, dass Kapitalerträge die Lebenskosten decken.",
    example: "Varianten: Lean FIRE (sehr sparsam leben), Fat FIRE (komfortabel), Barista FIRE (Teilzeitjob ergänzt die Entnahmen)." },
  { id: "fpr-060", cat: "finanzen", topic: "Entnahme", type: "quiz", emoji: "🔥", level: 3,
    q: "Was beschleunigt den Weg zu FIRE am stärksten?",
    options: ["Eine 1 % höhere Rendite", "Eine deutlich höhere Sparquote", "Ein günstigerer Broker", "Ein Wechsel von ausschüttend zu thesaurierend"], answer: 1,
    explain: "Die Sparquote wirkt doppelt: Mehr Geld fließt ins Depot, **und** die benötigte Zielsumme sinkt, weil du mit weniger Ausgaben lebst. Die Rendite kannst du kaum steuern – die Sparquote schon." },
  // ── Gesetzliche Rente ──
  { id: "fpr-061", cat: "finanzen", topic: "Gesetzliche Rente", type: "fact", emoji: "🏛️", level: 1,
    title: "Drei Säulen der Altersvorsorge",
    text: "1. Gesetzliche Rente (Pflicht für Arbeitnehmer), 2. betriebliche Altersversorgung (bAV), 3. private Vorsorge (Riester, Rürup, eigenes Depot, Immobilie). Erst alle zusammen sichern meist den Lebensstandard.",
    more: "Die gesetzliche Rente funktioniert im **Umlageverfahren**: Heutige Beiträge zahlen die heutigen Renten, es wird nichts für dich angespart. Deshalb hängt ihre Höhe stark von der Demografie ab. Private Vorsorge ist dagegen **kapitalgedeckt** – dein eigenes Vermögen." },
  { id: "fpr-062", cat: "finanzen", topic: "Gesetzliche Rente", type: "event", emoji: "👴", level: 2,
    year: "1889", title: "Bismarcks Invaliditäts- und Altersversicherung",
    text: "Das Deutsche Reich führt als eines der ersten Länder eine gesetzliche Rentenversicherung ein. Die Altersrente gab es ab 70 – ein Alter, das damals nur wenige erreichten.",
    more: "Die Rente war ursprünglich als Zuschuss gedacht, nicht als Vollversorgung. Bismarcks Sozialgesetze (Kranken- 1883, Unfall- 1884, Rentenversicherung 1889) sollten auch der Sozialdemokratie den Wind aus den Segeln nehmen." },
  { id: "fpr-063", cat: "finanzen", topic: "Gesetzliche Rente", type: "event", emoji: "📜", level: 3,
    year: "1957", title: "Große Rentenreform: die dynamische Rente",
    text: "Unter Adenauer wird die Rente auf das Umlageverfahren umgestellt und an die Lohnentwicklung gekoppelt. Die Renten steigen auf einen Schlag um rund 60 %.",
    more: "Grundlage war der „Generationenvertrag“: Die Erwerbstätigen finanzieren die Rentner. Das funktionierte bei vielen Kindern und hohem Wachstum hervorragend – im demografischen Wandel gerät es unter Druck." },
  { id: "fpr-064", cat: "finanzen", topic: "Gesetzliche Rente", type: "number", emoji: "🎫", level: 2,
    value: "40,79 €", label: "Monatsrente pro Entgeltpunkt (Rentenwert, ab 1.7.2025)",
    text: "Wer ein Jahr lang genau das Durchschnittsentgelt aller Versicherten verdient, erhält 1 Entgeltpunkt – und damit später 40,79 € Monatsrente brutto (Stand Juli 2025).",
    more: "Die „Standardrente“ (45 Jahre Durchschnittsverdienst = 45 Punkte) liegt damit bei rund 1.836 € brutto. Davon gehen noch Kranken- und Pflegeversicherung sowie ggf. Steuern ab. Der Rentenwert wird jährlich zum 1. Juli angepasst." },
  { id: "fpr-065", cat: "finanzen", topic: "Gesetzliche Rente", type: "quiz", emoji: "🧮", level: 2,
    q: "Du verdienst ein Jahr lang das 1,5-fache des Durchschnittsentgelts (unterhalb der Beitragsbemessungsgrenze). Wie viele Entgeltpunkte bekommst du?",
    options: ["1,0", "1,25", "2,0", "1,5"], answer: 3,
    explain: "Entgeltpunkte = eigenes Bruttoentgelt ÷ Durchschnittsentgelt. 1,5-faches Gehalt → 1,5 Punkte. Oberhalb der Beitragsbemessungsgrenze zählt das Einkommen nicht mehr – die Rente ist also gedeckelt." },
  { id: "fpr-066", cat: "finanzen", topic: "Gesetzliche Rente", type: "truefalse", emoji: "📉", level: 1,
    q: "Die gesetzliche Rente reicht für die meisten aus, um ihren gewohnten Lebensstandard im Alter zu halten.",
    answer: false,
    explain: "Das Rentenniveau liegt bei rund 48 % (Stand 2025) – eine Standardrente nach 45 Durchschnittsjahren entspricht also knapp der Hälfte des Durchschnittslohns, vor Steuern und Krankenversicherung. Die Differenz ist die **Rentenlücke**." },
  { id: "fpr-067", cat: "finanzen", topic: "Gesetzliche Rente", type: "flashcard", emoji: "🕳️", level: 1,
    term: "Rentenlücke",
    def: "Differenz zwischen dem, was du im Alter zum Leben brauchst, und dem, was gesetzliche (und betriebliche) Rente netto liefern. Sie muss privat geschlossen werden.",
    example: "Bedarf 2.400 € netto (heutige Kaufkraft), erwartete Rente 1.600 € netto → 800 € Lücke pro Monat, über ca. 20 Rentenjahre." },
  { id: "fpr-068", cat: "finanzen", topic: "Gesetzliche Rente", type: "whatif", emoji: "👶", level: 2,
    q: "Was passiert, wenn auf immer weniger Beitragszahler immer mehr Rentner kommen?",
    steps: ["Babyboomer gehen in Rente", "Weniger Einzahler je Rentner", "Druck auf Beiträge, Rentenniveau oder Rentenalter", "Bundeszuschuss aus Steuern wächst"],
    text: "Im Umlageverfahren gibt es nur drei Stellschrauben: höhere Beiträge, niedrigeres Rentenniveau, späterer Rentenbeginn – oder mehr Steuergeld. 1962 kamen rund sechs Beitragszahler auf einen Rentner, heute sind es etwa zwei." },
  { id: "fpr-069", cat: "finanzen", topic: "Gesetzliche Rente", type: "truefalse", emoji: "🧾", level: 2,
    q: "Auch die gesetzliche Rente kann einkommensteuerpflichtig sein.",
    answer: true,
    explain: "Stimmt: Seit 2005 gilt die **nachgelagerte Besteuerung**: Beiträge werden schrittweise steuerfrei gestellt, Renten dafür besteuert. Der steuerpflichtige Anteil hängt vom Rentenbeginn ab und steigt bis auf 100 % (Stand 2025: 83,5 % für Neurentner). Viele Rentner bleiben aber wegen des Grundfreibetrags steuerfrei." },
  { id: "fpr-070", cat: "finanzen", topic: "Gesetzliche Rente", type: "order", emoji: "🗓️", level: 3,
    q: "Bringe die Meilensteine der deutschen Altersvorsorge in die richtige zeitliche Reihenfolge:",
    items: ["Bismarcks Rentenversicherung (1889)", "Dynamische Rente unter Adenauer (1957)", "Einführung der Riester-Rente (2002)", "Rürup-Rente durch das Alterseinkünftegesetz (2005)"],
    explain: "Erst staatliche Grundsicherung, dann die Umlage-Rente nach Lohnentwicklung. Ab 2001/2002 senkte die Politik das Rentenniveau und förderte im Gegenzug die private, kapitalgedeckte Vorsorge (Riester, später Rürup)." },

  // ── Betriebsrente ──
  { id: "fpr-071", cat: "finanzen", topic: "Betriebsrente", type: "fact", emoji: "🏭", level: 3,
    title: "bAV: Vorsorge aus dem Bruttogehalt",
    text: "Bei der Entgeltumwandlung zahlst du Teile deines Bruttolohns in eine Betriebsrente ein. Beiträge sind bis 8 % der Beitragsbemessungsgrenze (RV) steuerfrei und bis 4 % sozialabgabenfrei (Stand 2025).",
    more: "Der Haken: **Nachgelagerte Besteuerung** – die spätere Betriebsrente ist voll steuerpflichtig, und es fallen Kranken- und Pflegeversicherungsbeiträge an (bei der KV mit Freibetrag). Zudem sinken gesetzliche Rentenansprüche leicht, weil weniger Beiträge fließen." },
  { id: "fpr-072", cat: "finanzen", topic: "Betriebsrente", type: "quiz", emoji: "🤝", level: 2,
    q: "Wie hoch ist der gesetzliche Pflichtzuschuss des Arbeitgebers bei Entgeltumwandlung, soweit er Sozialabgaben spart?",
    options: ["15 %", "5 %", "25 %", "50 %"], answer: 0,
    explain: "Seit 2019 für neue und seit 2022 für alle Verträge: 15 % des umgewandelten Betrags, soweit der Arbeitgeber Sozialversicherungsbeiträge spart. Viele Arbeitgeber zahlen freiwillig mehr – das macht die bAV oft erst richtig attraktiv." },
  { id: "fpr-073", cat: "finanzen", topic: "Betriebsrente", type: "truefalse", emoji: "🔎", level: 3,
    q: "Eine Betriebsrente per Entgeltumwandlung lohnt sich immer – egal, wie hoch Zuschuss und Kosten sind.",
    answer: false,
    explain: "Steuer- und Abgabenersparnis heute stehen Steuer, KV/PV-Beiträgen und Vertragskosten im Alter gegenüber. Ohne nennenswerten Arbeitgeberzuschuss und bei teuren Versicherungstarifen kann sie schlechter abschneiden als ein privates ETF-Depot. Vertrag immer durchrechnen." },

  // ── Private Vorsorge ──
  { id: "fpr-074", cat: "finanzen", topic: "Private Vorsorge", type: "fact", emoji: "🎁", level: 2,
    title: "Riester-Rente: Zulagen vom Staat",
    text: "Staatlich geförderte Privatrente: 175 € Grundzulage pro Jahr, 300 € je Kind (geboren ab 2008). Voll gibt es die Zulagen nur bei 4 % des Vorjahresbruttos als Gesamtbeitrag (max. 2.100 € inkl. Zulagen). Stand 2025.",
    more: "Besonders lohnend für Familien mit Kindern und Geringverdiener (hohe Zulagenquote). Kritik: hohe Kosten vieler Verträge, Beitragsgarantie drückt die Rendite, Rente im Alter voll steuerpflichtig. Eine Reform der geförderten Privatvorsorge ist seit Jahren in der politischen Diskussion." },
  { id: "fpr-075", cat: "finanzen", topic: "Private Vorsorge", type: "quiz", emoji: "👨‍👩‍👧", level: 2,
    q: "Eine Mutter mit zwei Kindern (geboren 2015 und 2018) erfüllt den Mindesteigenbeitrag. Wie hoch sind ihre jährlichen Riester-Zulagen (Stand 2025)?",
    options: ["175 €", "475 €", "550 €", "775 €"], answer: 3,
    explain: "175 € Grundzulage + 2 × 300 € Kinderzulage = 775 € pro Jahr. Für Kinder vor 2008 gäbe es nur 185 €. Bei kleinem Einkommen kann der Eigenanteil sehr gering sein – dann ist die Förderquote enorm." },
  { id: "fpr-076", cat: "finanzen", topic: "Private Vorsorge", type: "flashcard", emoji: "🧱", level: 3,
    term: "Rürup-Rente (Basisrente)",
    def: "Private Rentenversicherung der ersten Schicht: Beiträge sind seit 2023 bis zum Höchstbetrag zu 100 % als Sonderausgaben absetzbar. Dafür nur lebenslange Rente – nicht kündbar, nicht vererbbar, keine Kapitalauszahlung.",
    example: "Interessant für Selbstständige und Gutverdiener mit hohem Grenzsteuersatz: Steuervorteil heute, Rente im Alter (oft niedrigerer Steuersatz) voll steuerpflichtig." },
  { id: "fpr-077", cat: "finanzen", topic: "Private Vorsorge", type: "truefalse", emoji: "📦", level: 2,
    q: "Eine Kapitallebensversicherung ist ideal, weil sie Sparen und Absicherung clever in einem Produkt kombiniert.",
    answer: false,
    explain: "Verbraucherschützer raten meist ab: hohe Abschluss- und Verwaltungskosten, niedriger Garantiezins (Höchstrechnungszins 1,0 %, Stand 2025), wenig Flexibilität. Meist besser: Risikolebensversicherung (falls Hinterbliebene abzusichern sind) **plus** getrennte, günstige Geldanlage." },
  { id: "fpr-078", cat: "finanzen", topic: "Private Vorsorge", type: "whatif", emoji: "✂️", level: 3,
    q: "Was passiert, wenn du eine Kapitallebensversicherung schon nach wenigen Jahren kündigst?",
    steps: ["Abschlusskosten wurden zuerst verrechnet", "Rückkaufswert liegt unter den Einzahlungen", "Verlust wird endgültig", "Alternative prüfen: Beitragsfreistellung"],
    text: "Abschlusskosten werden auf die ersten Jahre verteilt (gesetzlich über mindestens 5 Jahre). Frühes Kündigen ist daher oft teuer. Bei Altverträgen mit hohem Garantiezins (z. B. 3–4 % aus den 1990er/2000er-Jahren) kann das Weiterführen sogar sinnvoll sein." },
  { id: "fpr-079", cat: "finanzen", topic: "Private Vorsorge", type: "quiz", emoji: "🛠️", level: 1,
    q: "Was ist der größte Vorteil eines eigenen ETF-Depots für die Altersvorsorge gegenüber Riester/Rürup?",
    options: ["Staatliche Zulagen", "Volle Flexibilität: jederzeit verfügbar, vererbbar, Sparrate frei änderbar", "Garantierte Mindestrendite", "Komplette Steuerfreiheit im Alter"], answer: 1,
    explain: "Das Depot gehört dir uneingeschränkt. Dafür gibt es keine Förderung und keine Garantie – die Disziplin, es nicht vorzeitig zu verbrauchen, musst du selbst aufbringen." },
  { id: "fpr-080", cat: "finanzen", topic: "Private Vorsorge", type: "event", emoji: "🧩", level: 2,
    year: "2002", title: "Start der Riester-Rente",
    text: "Benannt nach Arbeitsminister Walter Riester: Weil das gesetzliche Rentenniveau langfristig sinken sollte, förderte der Staat ab 2002 die private Zusatzvorsorge mit Zulagen und Steuervorteilen.",
    more: "Ein Paradigmenwechsel: weg vom Ziel, den Lebensstandard allein über die gesetzliche Rente zu sichern. Rund 16 Mio. Verträge wurden in der Spitze abgeschlossen, viele davon wurden später ruhend gestellt." },

  // ── Kapitalertragsteuer ──
  { id: "fpr-081", cat: "finanzen", topic: "Kapitalertragsteuer", type: "number", emoji: "✂️", level: 1,
    value: "26,375 %", label: "Abgeltungsteuer inkl. Soli (ohne Kirchensteuer)",
    text: "25 % Abgeltungsteuer plus 5,5 % Solidaritätszuschlag darauf: 25 % × 1,055 = 26,375 %. Gilt für Zinsen, Dividenden und Kursgewinne über dem Freibetrag.",
    more: "Mit Kirchensteuer steigt die Belastung leicht auf rund 27,8–28 %. Die Bank führt die Steuer automatisch ab („Abgeltung“). Anders als beim Einkommen gibt es keine Progression – ein Grund, warum sich Kapitalerträge für Gutverdiener steuerlich günstiger anfühlen als Arbeit." },
  { id: "fpr-082", cat: "finanzen", topic: "Kapitalertragsteuer", type: "event", emoji: "📅", level: 2,
    year: "2009", title: "Einführung der Abgeltungsteuer",
    text: "Seit 1.1.2009 sind Kursgewinne unabhängig von der Haltedauer steuerpflichtig. Vorher waren Aktiengewinne nach einem Jahr Spekulationsfrist steuerfrei.",
    more: "Vor 2009 gekaufte Aktien und Fonds („Altbestand“) blieben weitgehend steuerfrei – bei Fonds gilt seit 2018 ein Freibetrag von 100.000 € für Gewinne ab 2018. Deshalb hüten manche ältere Anleger ihre Altbestände besonders." },
  { id: "fpr-083", cat: "finanzen", topic: "Kapitalertragsteuer", type: "number", emoji: "🎁", level: 1,
    value: "1.000 €", label: "Sparerpauschbetrag pro Person und Jahr (seit 2023)",
    text: "Bis 1.000 € Kapitalerträge im Jahr sind steuerfrei, für zusammenveranlagte Ehepaare 2.000 €. Bis 2022 waren es 801 € bzw. 1.602 €.",
    more: "Er gilt für alle Kapitalerträge zusammen: Zinsen, Dividenden, Fondserträge, Kursgewinne. Tatsächliche Kosten (z. B. Depotgebühren) kann man nicht zusätzlich absetzen – sie sind mit dem Pauschbetrag abgegolten." },
  { id: "fpr-084", cat: "finanzen", topic: "Kapitalertragsteuer", type: "quiz", emoji: "📝", level: 1,
    q: "Wozu dient ein Freistellungsauftrag?",
    options: ["Er befreit dich ganz von der Steuerpflicht", "Er erlaubt der Bank, Erträge bis zum Sparerpauschbetrag ohne Steuerabzug auszuzahlen", "Er kündigt dein Depot", "Er meldet dein Konto beim Finanzamt ab"], answer: 1,
    explain: "Ohne Freistellungsauftrag zieht die Bank sofort 26,375 % ab – selbst wenn du unter 1.000 € bleibst. Zurück bekommst du das Geld dann nur über die Steuererklärung (Anlage KAP)." },
  { id: "fpr-085", cat: "finanzen", topic: "Kapitalertragsteuer", type: "truefalse", emoji: "✂️", level: 2,
    q: "Man kann den Sparerpauschbetrag per Freistellungsauftrag auf mehrere Banken aufteilen.",
    answer: true,
    explain: "Zum Beispiel 600 € beim Broker und 400 € bei der Tagesgeldbank. Die Summe aller Aufträge darf 1.000 € (bzw. 2.000 € bei Ehepaaren) nicht übersteigen. Tipp: Jährlich prüfen, wo die Erträge tatsächlich anfallen." },
  { id: "fpr-086", cat: "finanzen", topic: "Kapitalertragsteuer", type: "quiz", emoji: "🧮", level: 3,
    q: "Du verkaufst Anteile eines Aktien-ETFs mit 1.000 € Gewinn, Freibetrag bereits ausgeschöpft, keine Kirchensteuer. Wie viel Steuer fällt an?",
    options: ["Ca. 264 €", "Ca. 250 €", "Ca. 185 €", "0 €"], answer: 2,
    explain: "Bei Aktienfonds (mind. 51 % Aktien) sind 30 % der Erträge steuerfrei (**Teilfreistellung**). Steuerpflichtig: 700 € × 26,375 % ≈ 184,63 €. Effektiv also nur rund 18,5 % Steuer auf den Gewinn." },
  { id: "fpr-087", cat: "finanzen", topic: "Kapitalertragsteuer", type: "flashcard", emoji: "📆", level: 3,
    term: "Vorabpauschale",
    def: "Seit 2018 werden thesaurierende (und wenig ausschüttende) Fonds jährlich mit einem fiktiven Mindestertrag besteuert: Fondswert am Jahresanfang × Basiszins × 0,7 – höchstens der tatsächliche Wertzuwachs.",
    example: "Basiszins 2025: 2,53 %. 10.000 € Aktien-ETF → 177,10 € Vorabpauschale; nach 30 % Teilfreistellung 123,97 € steuerpflichtig. Wird im Januar des Folgejahres abgebucht und beim Verkauf angerechnet." },
  { id: "fpr-088", cat: "finanzen", topic: "Kapitalertragsteuer", type: "whatif", emoji: "📭", level: 1,
    q: "Was passiert, wenn du bei deiner Bank keinen Freistellungsauftrag einrichtest?",
    steps: ["Zinsen/Dividenden werden gutgeschrieben", "Bank zieht sofort 26,375 % Steuer ab", "Geld fehlt im Depot und arbeitet nicht", "Rückholung nur über die Steuererklärung"],
    text: "Ein vergessener Freistellungsauftrag ist kein Totalverlust, aber lästig: Du gibst dem Staat einen zinslosen Kredit. Einrichten dauert online wenige Minuten." },
  { id: "fpr-089", cat: "finanzen", topic: "Kapitalertragsteuer", type: "truefalse", emoji: "⏳", level: 2,
    q: "Gewinne aus Aktien und ETFs sind nach einem Jahr Haltedauer steuerfrei.",
    answer: false,
    explain: "Das galt nur bis Ende 2008. Heute sind Kursgewinne bei Wertpapieren immer abgeltungsteuerpflichtig. Die Ein-Jahres-Frist gibt es noch bei **privaten Veräußerungsgeschäften** wie physischem Gold (für Immobilien gelten zehn Jahre)." },
  { id: "fpr-090", cat: "finanzen", topic: "Kapitalertragsteuer", type: "quiz", emoji: "🎓", level: 3,
    q: "Für wen kann sich die Günstigerprüfung in der Steuererklärung lohnen?",
    options: ["Für alle mit Kapitalerträgen über 1.000 €", "Für Spitzenverdiener", "Für Menschen mit persönlichem Steuersatz unter 25 %, z. B. Studierende oder Rentner", "Nur für Selbstständige"], answer: 2,
    explain: "Dann werden die Kapitalerträge mit dem niedrigeren persönlichen Steuersatz statt mit 25 % besteuert. Das Finanzamt prüft auf Antrag (Anlage KAP), was günstiger ist – Nachteile entstehen dadurch nicht." },

  // ── Einkommensteuer ──
  { id: "fpr-091", cat: "finanzen", topic: "Einkommensteuer", type: "number", emoji: "🛡️", level: 1,
    value: "12.096 €", label: "Grundfreibetrag 2025 (Alleinstehende)",
    text: "Bis zu diesem zu versteuernden Einkommen pro Jahr zahlt man keine Einkommensteuer. Für zusammenveranlagte Ehepaare gilt das Doppelte. Für 2026 ist er auf 12.348 € gestiegen.",
    more: "Der Grundfreibetrag soll das Existenzminimum steuerfrei stellen und wird regelmäßig angehoben. Er ist der Grund, warum viele Studierende und Rentner mit kleinem Einkommen gar keine Steuer zahlen – und sich z. B. die Günstigerprüfung oder eine Nichtveranlagungsbescheinigung lohnen kann." },
  { id: "fpr-092", cat: "finanzen", topic: "Einkommensteuer", type: "flashcard", emoji: "📏", level: 2,
    term: "Grenzsteuersatz vs. Durchschnittssteuersatz",
    def: "Grenzsteuersatz: Steuer auf den nächsten zusätzlichen Euro. Durchschnittssteuersatz: gesamte Steuer geteilt durch das gesamte zu versteuernde Einkommen. Der Durchschnitt liegt immer unter dem Grenzsatz.",
    example: "Für Steuerspar-Entscheidungen (Werbungskosten, Rürup) zählt der **Grenzsteuersatz**: Jeder abgesetzte Euro spart genau diesen Prozentsatz." },
  { id: "fpr-093", cat: "finanzen", topic: "Einkommensteuer", type: "quiz", emoji: "🧮", level: 3,
    q: "Ledig, 50.000 € zu versteuerndes Einkommen (Tarif 2025): Wie hoch ist die Einkommensteuer ungefähr?",
    options: ["Ca. 17.500 € (35 %)", "Ca. 10.700 € (Ø ca. 21 %)", "Ca. 21.000 € (42 %)", "Ca. 7.000 € (14 %)"], answer: 1,
    explain: "Nach dem Tarif 2025 rund 10.690 € – ein Durchschnittssteuersatz von ca. 21 %. Der Grenzsteuersatz liegt dort bei etwa 35 %. Wer beides verwechselt, überschätzt seine Steuerlast deutlich. Soli fällt hier wegen der Freigrenze nicht an." },
  { id: "fpr-094", cat: "finanzen", topic: "Einkommensteuer", type: "truefalse", emoji: "💰", level: 1,
    q: "Eine Gehaltserhöhung kann dazu führen, dass man netto weniger hat, weil man in eine höhere Steuerstufe rutscht.",
    answer: false,
    explain: "Der deutsche Tarif ist **stufenlos progressiv**: Nur der zusätzliche Euro wird mit dem höheren Grenzsatz besteuert, nicht das ganze Einkommen. Mehr Brutto bedeutet bei der Einkommensteuer immer auch mehr Netto (Sonderfälle können Sozialleistungen betreffen)." },
  { id: "fpr-095", cat: "finanzen", topic: "Einkommensteuer", type: "order", emoji: "📶", level: 2,
    q: "Sortiere die Zonen des Einkommensteuertarifs (Stand 2025) vom niedrigsten zum höchsten Einkommen:",
    items: ["Grundfreibetrag: 0 %", "Eingangssteuersatz: 14 %", "Spitzensteuersatz: 42 % (ab ca. 68.500 €)", "„Reichensteuer“: 45 % (ab ca. 278.000 €)"],
    explain: "Dazwischen steigt der Grenzsteuersatz linear an (Progressionszonen). Die Werte gelten für Alleinstehende und das zu versteuernde Einkommen, nicht das Bruttogehalt." },
  { id: "fpr-096", cat: "finanzen", topic: "Einkommensteuer", type: "number", emoji: "💼", level: 2,
    value: "1.230 €", label: "Arbeitnehmer-Pauschbetrag (Werbungskosten, seit 2023)",
    text: "So viel Werbungskosten zieht das Finanzamt bei Arbeitnehmern automatisch ab – auch ohne Belege. Erst darüber lohnt sich der Einzelnachweis.",
    more: "Typische Werbungskosten: Fahrten zur Arbeit (Entfernungspauschale), Homeoffice-Pauschale, Arbeitsmittel, Fortbildungen, Bewerbungen, Umzug aus beruflichen Gründen, Kontoführung (pauschal 16 € anerkannt). Schon die Pendlerpauschale allein übersteigt die 1.230 € oft." },
  { id: "fpr-097", cat: "finanzen", topic: "Einkommensteuer", type: "quiz", emoji: "🚆", level: 2,
    q: "Einfache Strecke zur Arbeit 30 km, 220 Arbeitstage (Regel 2025: 0,30 €/km bis km 20, 0,38 € ab km 21). Wie hoch ist die Entfernungspauschale?",
    options: ["1.980 €", "2.508 €", "1.320 €", "2.156 €"], answer: 3,
    explain: "20 km × 0,30 € × 220 = 1.320 € plus 10 km × 0,38 € × 220 = 836 € → 2.156 €. Nur die einfache Strecke zählt. Damit liegt man allein schon über dem Arbeitnehmer-Pauschbetrag von 1.230 €." },
  { id: "fpr-098", cat: "finanzen", topic: "Einkommensteuer", type: "whatif", emoji: "📚", level: 3,
    q: "Was passiert, wenn du 1.000 € zusätzliche Werbungskosten absetzt und dein Grenzsteuersatz 35 % beträgt?",
    steps: ["Zu versteuerndes Einkommen sinkt um 1.000 €", "Steuer sinkt um den Grenzsteuersatz", "Erstattung: ca. 350 €", "Die Ausgabe kostet dich effektiv nur ~650 €"],
    text: "Absetzen heißt nicht „geschenkt“: Du bekommst nur deinen Grenzsteuersatz zurück. Trotzdem macht das berufliche Fortbildungen, Laptops oder Fachbücher spürbar günstiger." },
  { id: "fpr-099", cat: "finanzen", topic: "Einkommensteuer", type: "truefalse", emoji: "📨", level: 1,
    q: "Für normale Angestellte lohnt sich eine freiwillige Steuererklärung meistens nicht.",
    answer: false,
    explain: "Die Mehrheit bekommt Geld zurück – im Schnitt rund 1.000 €. Die Lohnsteuer berücksichtigt nur Pauschalen. Freiwillige Erklärungen kann man bis zu vier Jahre rückwirkend abgeben (z. B. bis Ende 2026 für 2022)." },
  { id: "fpr-100", cat: "finanzen", topic: "Einkommensteuer", type: "quiz", emoji: "🏡", level: 1,
    q: "Wie hoch ist die Homeoffice-Pauschale (Stand 2025)?",
    options: ["6 € pro Tag, max. 1.260 € im Jahr", "5 € pro Tag, max. 600 € im Jahr", "10 € pro Tag, unbegrenzt", "2 € pro Tag, max. 400 € im Jahr"], answer: 0,
    explain: "Seit 2023: 6 € pro Homeoffice-Tag für bis zu 210 Tage = max. 1.260 €. Ein separates Arbeitszimmer ist dafür nicht nötig. Sie zählt zu den Werbungskosten, also zum Arbeitnehmer-Pauschbetrag hinzu – nicht zusätzlich." },

  // ── Sozialabgaben ──
  { id: "fpr-101", cat: "finanzen", topic: "Sozialabgaben", type: "fact", emoji: "🧾", level: 1,
    title: "Vom Brutto zum Netto: Wohin geht dein Geld?",
    text: "Vom Bruttolohn gehen ab: Lohnsteuer (+ ggf. Soli und Kirchensteuer) sowie dein Anteil an Renten-, Kranken-, Pflege- und Arbeitslosenversicherung – zusammen rund 20 % des Bruttos nur für die Sozialversicherung.",
    more: "Die Sozialbeiträge teilen sich Arbeitnehmer und Arbeitgeber grob hälftig. Deine echten Arbeitskosten für den Arbeitgeber liegen also rund 20 % über deinem Brutto. Bei einem mittleren Single-Gehalt bleiben netto oft nur etwa 60–65 % übrig." },
  { id: "fpr-102", cat: "finanzen", topic: "Sozialabgaben", type: "number", emoji: "🧓", level: 2,
    value: "18,6 %", label: "Beitragssatz zur Rentenversicherung (Stand 2025)",
    text: "Je zur Hälfte von Arbeitnehmer (9,3 %) und Arbeitgeber (9,3 %) getragen – der größte Einzelposten der Sozialabgaben.",
    more: "Beiträge fallen nur bis zur **Beitragsbemessungsgrenze** an (2025: 96.600 € pro Jahr). Wer mehr verdient, zahlt auf den Rest keine Rentenbeiträge, erhält dafür aber auch keine zusätzlichen Rentenpunkte." },
  { id: "fpr-103", cat: "finanzen", topic: "Sozialabgaben", type: "quiz", emoji: "🧢", level: 2,
    q: "Was bewirkt die Beitragsbemessungsgrenze?",
    options: ["Ab ihr ist man von der Steuer befreit", "Ab ihr verdoppeln sich die Beiträge", "Einkommen darüber ist beitragsfrei – die Sozialbeiträge sind gedeckelt", "Sie ist der Mindestlohn für Sozialversicherungspflicht"], answer: 2,
    explain: "Bis zur Grenze steigt der Beitrag mit dem Gehalt, darüber nicht mehr. Für die Krankenversicherung liegt sie niedriger als für die Rente (2025: 66.150 € vs. 96.600 € pro Jahr)." },
  { id: "fpr-104", cat: "finanzen", topic: "Sozialabgaben", type: "order", emoji: "📊", level: 3,
    q: "Sortiere die allgemeinen Beitragssätze der Sozialversicherung (Stand 2025) vom höchsten zum niedrigsten:",
    items: ["Rentenversicherung: 18,6 %", "Krankenversicherung: 14,6 % + Zusatzbeitrag", "Pflegeversicherung: 3,6 %", "Arbeitslosenversicherung: 2,6 %"],
    explain: "Der durchschnittliche KV-Zusatzbeitrag lag 2025 bei 2,5 %. Kinderlose ab 23 zahlen in der Pflegeversicherung einen Zuschlag von 0,6 Prozentpunkten." },
  // ── Kredite ──
  { id: "fpr-105", cat: "finanzen", topic: "Kredite", type: "fact", emoji: "🔍", level: 1,
    title: "Effektivzins schlägt Sollzins",
    text: "Der Sollzins ist der reine Zins auf das Darlehen. Der effektive Jahreszins enthält zusätzlich Pflichtkosten (z. B. Bearbeitungsgebühren) und die Wirkung unterjähriger Zahlungen. Zum Vergleich von Angeboten zählt nur der Effektivzins.",
    more: "Banken müssen den effektiven Jahreszins nach der Preisangabenverordnung angeben. Achtung bei Lockangeboten mit „ab“-Zinsen: Der tatsächliche Zins hängt oft von deiner Bonität ab. Optionale Zusatzprodukte wie eine Restschuldversicherung sind teils nicht eingerechnet – und machen Kredite deutlich teurer." },
  { id: "fpr-106", cat: "finanzen", topic: "Kredite", type: "quiz", emoji: "⚖️", level: 1,
    q: "Du vergleichst zwei Ratenkredit-Angebote. Welche Kennzahl ist entscheidend?",
    options: ["Der effektive Jahreszins", "Der gebundene Sollzins", "Die Höhe der Monatsrate", "Die Laufzeit"], answer: 0,
    explain: "Nur der Effektivzins macht Angebote mit unterschiedlichen Gebühren und Zahlungsweisen vergleichbar. Eine niedrige Monatsrate kann einfach eine lange – und damit teure – Laufzeit bedeuten." },
  { id: "fpr-107", cat: "finanzen", topic: "Kredite", type: "whatif", emoji: "💳", level: 2,
    q: "Was passiert, wenn du bei der Kreditkarte nur den Mindestbetrag zahlst?",
    steps: ["3.000 € Schulden, 18 % Zins", "Mindestrate: 2 % (min. 25 €)", "Rate deckt kaum mehr als die Zinsen", "Rückzahlung dauert ca. 21 Jahre", "Gesamt gezahlt: rund 9.000 €"],
    text: "Revolving-Kreditkarten sind bequem, aber teuer: Die Tilgung ist anfangs winzig, der Zinseszins arbeitet gegen dich. Mit festen 100 € pro Monat wäre dieselbe Schuld in rund 3,5 Jahren für ca. 4.000 € getilgt." },
  { id: "fpr-108", cat: "finanzen", topic: "Kredite", type: "fact", emoji: "🚨", level: 1,
    title: "Der Dispo: teuerster Alltagskredit",
    text: "Der Dispositionskredit erlaubt, das Girokonto zu überziehen. Die Zinsen liegen häufig um die 10 % oder mehr pro Jahr – ein Vielfaches von Ratenkredit- oder Baufinanzierungszinsen.",
    more: "Er ist nur für kurze Engpässe gedacht. Wer dauerhaft im Dispo steht, sollte auf einen günstigeren Ratenkredit umschulden und einen Notgroschen aufbauen. Banken müssen Dauernutzern übrigens eine Beratung zu günstigeren Alternativen anbieten." },
  { id: "fpr-109", cat: "finanzen", topic: "Kredite", type: "quiz", emoji: "🏠", level: 2,
    q: "Annuitätendarlehen über 300.000 €, 4 % Sollzins, 2 % anfängliche Tilgung. Wie hoch ist die Monatsrate?",
    options: ["1.000 €", "500 €", "1.200 €", "1.500 €"], answer: 3,
    explain: "(4 % + 2 %) × 300.000 € = 18.000 € pro Jahr = 1.500 € pro Monat. Im ersten Monat sind davon 1.000 € Zins und 500 € Tilgung. Die Rate bleibt gleich, der Tilgungsanteil wächst mit jeder Zahlung." },
  { id: "fpr-110", cat: "finanzen", topic: "Kredite", type: "whatif", emoji: "🐌", level: 3,
    q: "Was passiert, wenn du bei 300.000 € und 4 % Zins nur 1 % statt 2 % anfänglich tilgst?",
    steps: ["Rate sinkt von 1.500 € auf 1.250 €", "Tilgungsanteil ist anfangs nur halb so hoch", "Laufzeit: ca. 40 statt ca. 28 Jahre", "Viel mehr Zinsen über die Gesamtlaufzeit"],
    text: "Niedrige Tilgung wirkt verlockend, verlängert die Laufzeit aber drastisch – oft bis in die Rente. Zudem bleibt nach Ende der Zinsbindung eine hohe Restschuld, die zu dann unbekannten Zinsen anschlussfinanziert werden muss." },
  { id: "fpr-111", cat: "finanzen", topic: "Kredite", type: "fact", emoji: "🗂️", level: 2,
    title: "Schufa: dein Bonitäts-Gedächtnis",
    text: "Die Schufa speichert Konten, Kredite, Kreditkarten, Handyverträge und Zahlungsausfälle. Daraus berechnet sie einen Score, der Kreditentscheidungen und Konditionen beeinflusst.",
    more: "Du kannst nach Art. 15 DSGVO eine kostenlose Datenkopie anfordern – und falsche Einträge korrigieren lassen. Tipp: Bei Kreditvergleichen eine „Anfrage Kreditkonditionen“ statt „Anfrage Kredit“ stellen lassen; die Konditionsanfrage ist für andere Banken nicht score-relevant." },
  { id: "fpr-112", cat: "finanzen", topic: "Kredite", type: "truefalse", emoji: "👀", level: 1,
    q: "Eine Selbstauskunft deiner eigenen Schufa-Daten hat keinen Einfluss auf deinen Score.",
    answer: true,
    explain: "Stimmt. Regelmäßig nachsehen ist sogar sinnvoll, um fehlerhafte Einträge zu entdecken – die können eine Kreditzusage oder einen Mietvertrag kosten." },
  { id: "fpr-113", cat: "finanzen", topic: "Kredite", type: "order", emoji: "🧹", level: 2,
    q: "Mehrere Schulden, Extra-Geld übrig: Sortiere, welche du nach der Lawinen-Methode zuerst tilgst:",
    items: ["Kreditkarte mit 18 %", "Dispo mit 11 %", "Ratenkredit mit 6 %", "Baufinanzierung mit 3,5 %"],
    explain: "Die Lawinen-Methode tilgt zuerst die teuerste Schuld – das spart mathematisch am meisten Zinsen. Die Schneeball-Methode (kleinste Schuld zuerst) bringt schnellere Erfolgserlebnisse und hilft manchen psychologisch." },
  { id: "fpr-114", cat: "finanzen", topic: "Kredite", type: "quiz", emoji: "🔒", level: 3,
    q: "Was passiert am Ende der Zinsbindung einer Baufinanzierung?",
    options: ["Die Restschuld wird erlassen", "Der Kredit muss sofort komplett zurückgezahlt werden", "Für die Restschuld wird ein neuer Zins zu dann aktuellen Marktkonditionen vereinbart", "Der alte Zins gilt automatisch weiter"], answer: 2,
    explain: "Die **Anschlussfinanzierung** erfolgt zu den Zinsen, die dann gelten – das ist das Zinsänderungsrisiko. Wer 2021 mit 1 % finanziert hat, musste bei Verlängerung oft 3–4 % zahlen. Längere Zinsbindung kostet etwas mehr, bringt aber Planungssicherheit." },
  { id: "fpr-115", cat: "finanzen", topic: "Kredite", type: "whatif", emoji: "🛋️", level: 2,
    q: "Was passiert, wenn du ein neues Sofa mit „0 %-Finanzierung“ kaufst?",
    steps: ["Rate wirkt klein, Kauf fällt leichter", "Ein Kredit wird bei der Schufa vermerkt", "Oft teure Zusatzversicherung angeboten", "Mehrere Raten summieren sich unbemerkt"],
    text: "0 % ist oft ein Verkaufsinstrument: Der Händler finanziert den Zins über den Preis oder Zusatzprodukte. Man kauft mehr und teurer, als man bar bezahlen würde. Faustregel: Konsum nur finanzieren, wenn es wirklich nicht anders geht." },

  // ── Immobilien ──
  { id: "fpr-116", cat: "finanzen", topic: "Immobilien", type: "number", emoji: "🏘️", level: 2,
    value: "3,5–6,5 %", label: "Grunderwerbsteuer je nach Bundesland",
    text: "Die Länder legen den Satz selbst fest: Bayern verlangt 3,5 %, mehrere Länder wie NRW, Brandenburg oder Schleswig-Holstein 6,5 % des Kaufpreises.",
    more: "Bei 400.000 € Kaufpreis sind das 14.000 € oder 26.000 € – je nach Wohnort. Die Grunderwerbsteuer kann nicht finanziert werden „wie das Haus“: Banken erwarten meist, dass Kaufnebenkosten aus Eigenkapital bezahlt werden." },
  { id: "fpr-117", cat: "finanzen", topic: "Immobilien", type: "quiz", emoji: "🧾", level: 2,
    q: "Wohnung für 400.000 € in NRW: 6,5 % Grunderwerbsteuer, ca. 2 % Notar und Grundbuch, 3,57 % Maklerprovision. Wie hoch sind die Kaufnebenkosten?",
    options: ["Ca. 48.000 €", "Ca. 26.000 €", "Ca. 34.000 €", "Ca. 60.000 €"], answer: 0,
    explain: "26.000 + 8.000 + 14.280 = 48.280 € – rund 12 % des Kaufpreises. Dieses Geld ist „weg“ und erhöht den Wert der Immobilie nicht. Seit Ende 2020 teilen sich Käufer und Verkäufer die Maklerprovision bei Wohnungen und Einfamilienhäusern in der Regel." },
  { id: "fpr-118", cat: "finanzen", topic: "Immobilien", type: "fact", emoji: "🔑", level: 3,
    title: "Kaufen oder mieten? Der Kaufpreisfaktor",
    text: "Kaufpreis ÷ Jahresnettokaltmiete einer vergleichbaren Wohnung. Faustregel: Unter ca. 20 spricht viel fürs Kaufen, über ca. 25–30 oft fürs Mieten und Investieren der Differenz.",
    more: "Beispiel: 450.000 € Kaufpreis, vergleichbare Miete 1.250 €/Monat = 15.000 €/Jahr → Faktor 30. Entscheidend ist der faire Vergleich: Der Mieter muss die gesparte Differenz (Eigenkapital, Instandhaltung, Nebenkosten) diszipliniert anlegen. Kaufen ist oft eher eine Lebensstil- als eine reine Renditeentscheidung." },
  { id: "fpr-119", cat: "finanzen", topic: "Immobilien", type: "truefalse", emoji: "🗑️", level: 1,
    q: "Miete ist rausgeschmissenes Geld – kaufen ist immer besser.",
    answer: false,
    explain: "Auch Eigentümer haben „verlorene“ Kosten: Zinsen, Kaufnebenkosten, Instandhaltung, Grundsteuer und entgangene Rendite auf das Eigenkapital. Miete kauft Flexibilität. Ob Kaufen besser ist, hängt von Preis, Zins, Haltedauer und Disziplin des Mieters ab." },
  { id: "fpr-120", cat: "finanzen", topic: "Immobilien", type: "whatif", emoji: "🏗️", level: 3,
    q: "Was passiert, wenn du eine 400.000-€-Immobilie mit 100.000 € Eigenkapital kaufst und sie 10 % an Wert gewinnt – oder verliert?",
    steps: ["Kredit: 300.000 €, bleibt gleich", "+10 % Wert = +40.000 € → +40 % aufs Eigenkapital", "−10 % Wert = −40.000 € → −40 % aufs Eigenkapital", "Hebel wirkt in beide Richtungen"],
    text: "Das ist der **Leverage-Effekt**: Fremdkapital vervielfacht Gewinne und Verluste bezogen auf dein Eigenkapital (hier vereinfacht ohne Nebenkosten und Zinsen). Er lohnt sich nur, wenn die Rendite der Immobilie über dem Kreditzins liegt." },
  { id: "fpr-121", cat: "finanzen", topic: "Immobilien", type: "fact", emoji: "🧱", level: 1,
    title: "Eigenkapital: Wie viel braucht man?",
    text: "Faustregel: Mindestens die Kaufnebenkosten (10–15 %) plus idealerweise 10–20 % des Kaufpreises aus eigenem Geld. Mehr Eigenkapital bedeutet bessere Zinsen und weniger Risiko.",
    more: "Vollfinanzierungen (110 %) sind möglich, aber teurer und riskanter: Bei sinkenden Preisen ist man schnell „unter Wasser“. Faustregel für die Rate: nicht mehr als etwa 35–40 % des Nettoeinkommens – und Rücklagen für Instandhaltung einplanen." },
  { id: "fpr-122", cat: "finanzen", topic: "Immobilien", type: "quiz", emoji: "🏷️", level: 3,
    q: "Du verkaufst eine vermietete Eigentumswohnung nach 6 Jahren mit Gewinn. Wie wird der Gewinn steuerlich behandelt?",
    options: ["Steuerfrei nach einem Jahr", "Pauschal mit 25 % Abgeltungsteuer", "Er ist immer steuerfrei", "Mit dem persönlichen Einkommensteuersatz, da die 10-Jahres-Frist nicht abgelaufen ist"], answer: 3,
    explain: "Für Immobilien gilt eine **Spekulationsfrist von 10 Jahren** (privates Veräußerungsgeschäft). Ausnahme: Selbst genutzte Immobilien sind steuerfrei, wenn man sie im Verkaufsjahr und den beiden Jahren davor selbst bewohnt hat." },
  { id: "fpr-123", cat: "finanzen", topic: "Immobilien", type: "whatif", emoji: "📈", level: 2,
    q: "Was passiert, wenn der Bauzins für deine Finanzierung von 1 % auf 4 % steigt?",
    steps: ["Darlehen 300.000 €, 2 % Tilgung", "Bei 1 %: Rate 750 € im Monat", "Bei 4 %: Rate 1.500 € im Monat", "Leistbarer Kaufpreis sinkt stark"],
    text: "Genau das geschah 2022: Die Bauzinsen stiegen innerhalb weniger Monate deutlich. Viele Kaufinteressenten konnten sich dieselbe Wohnung nicht mehr leisten, die Nachfrage sank – und die Immobilienpreise in Deutschland gaben 2023 spürbar nach." },

  // ── Versicherungen ──
  { id: "fpr-124", cat: "finanzen", topic: "Versicherungen", type: "number", emoji: "🛡️", level: 1,
    value: "10 Mio. €", label: "Mindest-Deckungssumme für die Privathaftpflicht (Empfehlung)",
    text: "Die Privathaftpflicht ist die wichtigste Versicherung überhaupt – kostet oft unter 100 € im Jahr und deckt Schäden, die du anderen zufügst.",
    more: "In Deutschland haftet man für fahrlässig verursachte Schäden unbegrenzt mit dem gesamten Vermögen und künftigen Einkommen (§ 823 BGB). Ein Fahrradunfall mit schwer verletzter Person kann Millionen kosten. Verbraucherschützer empfehlen daher hohe Deckungssummen von mindestens 10 Mio. €." },
  { id: "fpr-125", cat: "finanzen", topic: "Versicherungen", type: "quiz", emoji: "🩺", level: 1,
    q: "Welche Versicherung gilt für Berufseinsteiger als eine der wichtigsten – nach der Privathaftpflicht?",
    options: ["Handyversicherung", "Reisegepäckversicherung", "Berufsunfähigkeitsversicherung", "Glasbruchversicherung"], answer: 2,
    explain: "Deine Arbeitskraft ist in jungen Jahren dein größtes Vermögen – oft über eine Million Euro Lebenseinkommen. Die BU sichert es ab. Handy oder Gepäck dagegen kannst du im Ernstfall selbst ersetzen." },
  { id: "fpr-126", cat: "finanzen", topic: "Versicherungen", type: "fact", emoji: "🧠", level: 2,
    title: "Warum die BU so wichtig ist",
    text: "Wer nach dem 1.1.1961 geboren ist, hat keinen gesetzlichen Berufsschutz mehr. Der Staat zahlt nur eine Erwerbsminderungsrente – voll nur, wenn man in **keinem** Job mehr als 3 Stunden täglich arbeiten kann.",
    more: "Die EM-Rente ist meist niedrig und reicht selten zum Leben. Häufigste Ursache für Berufsunfähigkeit sind psychische Erkrankungen, nicht Unfälle. Je jünger und gesünder man abschließt, desto günstiger der Beitrag – Vorerkrankungen können später den Abschluss verhindern." },
  { id: "fpr-127", cat: "finanzen", topic: "Versicherungen", type: "whatif", emoji: "🚲", level: 1,
    q: "Was passiert, wenn du ohne Haftpflichtversicherung einen Radunfall verursachst?",
    steps: ["Fußgänger wird schwer verletzt", "Forderungen: Behandlung, Schmerzensgeld, Verdienstausfall", "Summe kann in die Millionen gehen", "Du haftest mit Vermögen und künftigem Einkommen"],
    text: "Gegen dich kann ein Titel erwirkt werden, der 30 Jahre vollstreckbar ist; gepfändet wird alles über der Pfändungsfreigrenze. Für unter 100 € im Jahr ist dieses Existenzrisiko abgesichert." },
  { id: "fpr-128", cat: "finanzen", topic: "Versicherungen", type: "truefalse", emoji: "🏚️", level: 2,
    q: "Die Hausratversicherung zahlt auch, wenn das Dach deines Hauses durch einen Sturm beschädigt wird.",
    answer: false,
    explain: "Hausrat deckt die beweglichen Dinge in der Wohnung (Möbel, Kleidung, Elektronik) – z. B. bei Einbruch, Feuer, Leitungswasser. Schäden am Gebäude selbst sind Sache der **Wohngebäudeversicherung** des Eigentümers." },
  { id: "fpr-129", cat: "finanzen", topic: "Versicherungen", type: "quiz", emoji: "🛋️", level: 3,
    q: "Hausrat: Versicherungssumme 30.000 €, tatsächlicher Wert 60.000 €, Schaden 10.000 €, kein Unterversicherungsverzicht. Was zahlt die Versicherung?",
    options: ["5.000 €", "10.000 €", "30.000 €", "0 €"], answer: 0,
    explain: "Bei Unterversicherung wird anteilig gezahlt: 30.000 ÷ 60.000 = 50 % → 5.000 €. Schutz: Versicherungssumme anpassen oder einen Tarif mit **Unterversicherungsverzicht** (oft ab ca. 650 € pro m² Wohnfläche) wählen." },
  { id: "fpr-130", cat: "finanzen", topic: "Versicherungen", type: "truefalse", emoji: "📱", level: 1,
    q: "Gute Finanzplanung heißt: möglichst jedes Risiko versichern, auch kleine wie Handy oder Brille.",
    answer: false,
    explain: "Versicherungen lohnen sich für Risiken, die dich finanziell ruinieren können (Haftpflicht, BU, Krankheit). Kleine Schäden zahlt man besser selbst – im Durchschnitt kostet jede Versicherung mehr, als sie auszahlt, sonst könnte der Versicherer nicht existieren." },

  // ── Sparkonten ──
  { id: "fpr-131", cat: "finanzen", topic: "Sparkonten", type: "number", emoji: "🏦", level: 1,
    value: "100.000 €", label: "Gesetzliche Einlagensicherung pro Kunde und Bank",
    text: "In der EU sind Einlagen (Giro-, Tages-, Festgeld) bis 100.000 € pro Person und Bank gesetzlich geschützt – auch bei einer Bankpleite.",
    more: "Bei Gemeinschaftskonten gilt der Schutz pro Kontoinhaber. Die Auszahlung soll innerhalb von 7 Arbeitstagen erfolgen. Bei Auslandsbanken haftet die Sicherung des jeweiligen EU-Landes – deren Stärke hängt auch von der Bonität des Staates ab. Wer mehr hat, verteilt auf mehrere Banken." },
  { id: "fpr-132", cat: "finanzen", topic: "Sparkonten", type: "quiz", emoji: "🧮", level: 2,
    q: "Du hast 150.000 € auf dem Tagesgeldkonto einer einzigen Bank, die pleitegeht. Wie viel ist durch die gesetzliche Einlagensicherung garantiert?",
    options: ["150.000 €", "100.000 €", "50.000 €", "20.000 €"], answer: 1,
    explain: "Gesetzlich 100.000 € pro Kunde und Bank. Darüber hinaus helfen eventuell freiwillige Sicherungssysteme der Banken – darauf gibt es aber keinen Rechtsanspruch. Deshalb größere Summen auf mehrere Institute verteilen." },
  { id: "fpr-133", cat: "finanzen", topic: "Sparkonten", type: "fact", emoji: "🔐", level: 1,
    title: "Tagesgeld vs. Festgeld",
    text: "Tagesgeld: täglich verfügbar, Zins variabel und kann jederzeit sinken. Festgeld: Zins für eine feste Laufzeit garantiert, das Geld ist bis dahin meist gebunden.",
    more: "Praxis: Notgroschen aufs Tagesgeld, planbare Ausgaben (z. B. Auto in 2 Jahren) aufs Festgeld. Eine **Festgeld-Leiter** (mehrere Festgelder mit gestaffelten Laufzeiten) kombiniert höhere Zinsen mit regelmäßiger Verfügbarkeit. Vorsicht vor Lockzinsen, die nur für Neukunden wenige Monate gelten." },
  { id: "fpr-134", cat: "finanzen", topic: "Sparkonten", type: "quiz", emoji: "📆", level: 1,
    q: "10.000 € Festgeld zu 3 % pro Jahr, 2 Jahre, Zinsen werden mitverzinst. Wie viel hast du am Ende (vor Steuern)?",
    options: ["10.300 €", "10.600 €", "10.609 €", "10.900 €"], answer: 2,
    explain: "10.000 × 1,03 × 1,03 = 10.609 €. Die 9 € Unterschied zu 10.600 € sind Zinsen auf die Zinsen des ersten Jahres – klein im Beispiel, aber genau das Prinzip, das über Jahrzehnte große Summen erzeugt." },
  { id: "fpr-135", cat: "finanzen", topic: "Sparkonten", type: "whatif", emoji: "🏛️", level: 3,
    q: "Was passiert, wenn die EZB die Leitzinsen senkt?",
    steps: ["Banken refinanzieren sich günstiger", "Tagesgeldzinsen sinken meist rasch", "Laufende Festgelder behalten ihren Zins", "Neue Festgelder und Kredite werden billiger"],
    text: "Tagesgeld reagiert schnell, weil der Zins variabel ist. Wer bei absehbar fallenden Zinsen einen Teil fest anlegt, sichert sich das höhere Niveau. Zugleich werden Kredite günstiger und Anleihekurse steigen tendenziell." },
  { id: "fpr-136", cat: "finanzen", topic: "Sparkonten", type: "truefalse", emoji: "📂", level: 3,
    q: "Die Einlagensicherung von 100.000 € schützt auch deine ETFs und Aktien im Depot bei einer Bankpleite.",
    answer: false,
    explain: "Sie gilt nur für Einlagen. Wertpapiere brauchen sie aber nicht: Sie bleiben dein Eigentum und werden bei einer Pleite der Depotbank nicht Teil der Insolvenzmasse, sondern auf eine andere Bank übertragen. Nur Guthaben auf dem Verrechnungskonto sind Einlagen." },

  // ── Anlageklassen ──
  { id: "fpr-137", cat: "finanzen", topic: "Anlageklassen", type: "fact", emoji: "🥇", level: 2,
    title: "Gold: Krisenschutz ohne laufende Erträge",
    text: "Gold zahlt weder Zinsen noch Dividenden – Rendite entsteht nur durch Preisänderungen. Es gilt als Krisenwährung, schwankt aber selbst stark und hatte schon jahrzehntelange Durststrecken.",
    more: "Nach dem Hoch von 1980 dauerte es real (inflationsbereinigt) Jahrzehnte, bis Gold dieses Niveau wieder erreichte. Viele Anleger halten Gold daher nur als kleine Beimischung zur Absicherung. Aktien sind dagegen Anteile an Unternehmen, die Gewinne erwirtschaften – daher langfristig der stärkere Renditemotor." },
  { id: "fpr-138", cat: "finanzen", topic: "Anlageklassen", type: "truefalse", emoji: "🪙", level: 2,
    q: "Gewinne aus physischem Gold sind in Deutschland nach mehr als einem Jahr Haltedauer steuerfrei.",
    answer: true,
    explain: "Physisches Gold fällt unter private Veräußerungsgeschäfte (§ 23 EStG), nicht unter die Abgeltungsteuer. Nach Ablauf eines Jahres ist der Gewinn steuerfrei. Anlagegold ist zudem von der Umsatzsteuer befreit, Silber nicht." },
  { id: "fpr-139", cat: "finanzen", topic: "Anlageklassen", type: "quiz", emoji: "⚖️", level: 1,
    q: "Was ist der grundlegende Nachteil von Gold als langfristige Hauptanlage?",
    options: ["Es ist in Deutschland verboten", "Man kann es nicht verkaufen", "Es verliert durch Inflation automatisch an Wert", "Es erwirtschaftet keine laufenden Erträge wie Zinsen oder Dividenden"], answer: 3,
    explain: "Ein Unternehmen produziert Gewinne, eine Anleihe Zinsen – ein Goldbarren nichts. Sein Preis hängt allein von Angebot, Nachfrage und Stimmung ab. Dafür hat Gold in Krisen oft stabilisiert." },
  { id: "fpr-140", cat: "finanzen", topic: "Anlageklassen", type: "order", emoji: "🎚️", level: 1,
    q: "Sortiere die Anlagen nach typischem Risiko – vom niedrigsten zum höchsten:",
    items: ["Tagesgeld bei einer Bank (bis 100.000 €)", "Bundesanleihe", "Breiter Welt-Aktien-ETF", "Einzelaktie eines jungen Start-ups"],
    explain: "Mit dem Risiko steigt auch die erwartete Rendite – das ist die **Risikoprämie**. Die Bundesanleihe hat zwar kaum Ausfallrisiko, aber Kursschwankungen bei Zinsänderungen. Eine Einzelaktie kann komplett wertlos werden, ein Welt-ETF praktisch nicht." },

  // ── Finanzmythen ──
  { id: "fpr-141", cat: "finanzen", topic: "Finanzmythen", type: "truefalse", emoji: "🏠", level: 2,
    q: "Immobilienpreise in Deutschland können nicht fallen – Betongold ist immer sicher.",
    answer: false,
    explain: "2023 fielen die Wohnimmobilienpreise laut Statistischem Bundesamt um rund 8 % – der stärkste Rückgang seit Beginn der Zeitreihe 2000. In schrumpfenden Regionen sinken Preise auch langfristig. Immobilien sind zudem oft ein Klumpenrisiko." },
  { id: "fpr-142", cat: "finanzen", topic: "Finanzmythen", type: "truefalse", emoji: "🎰", level: 1,
    q: "Aktien sind Glücksspiel – an der Börse kann man nur zocken.",
    answer: false,
    explain: "Beim Glücksspiel ist die erwartete Rendite negativ, bei Aktien positiv: Unternehmen erwirtschaften Gewinne. Zocken wird es durch Konzentration, Hebel und kurzfristiges Hin und Her. Breit gestreut und lange gehalten sind Aktien Beteiligung an der Weltwirtschaft." },
  { id: "fpr-143", cat: "finanzen", topic: "Finanzmythen", type: "quiz", emoji: "🤵", level: 2,
    q: "Woran verdient ein klassischer Bankberater, der dir einen aktiven Fonds empfiehlt, typischerweise?",
    options: ["Gar nicht – die Beratung ist eine kostenlose Serviceleistung", "Nur an einem festen Monatsgehalt ohne Bezug zum Produkt", "Am Ausgabeaufschlag und an laufenden Bestandsprovisionen aus den Fondskosten", "An einem Anteil deiner Steuererstattung"], answer: 2,
    explain: "Provisionsberatung ist nicht kostenlos – du bezahlst über Produktkosten. Das ist nicht illegal, schafft aber Interessenkonflikte. Alternative: Honorarberatung (du zahlst direkt, Provisionen werden durchgereicht) oder sich selbst einlesen." },
);
